import math

def calculate_sine(angle):
    """Calculate the sine of an angle."""
    return math.sin(math.radians(angle))

def calculate_cosine(angle):
    """Calculate the cosine of an angle."""
    return math.cos(math.radians(angle))

def main():
    while True:
        print("Scientific Calculator")
        print("1. Calculate sine of an angle")
        print("2. Calculate cosine of an angle")
        print("3. Exit")

        choice = input("Enter your choice: ")

        if choice == "1":
            angle = float(input("Enter the angle in degrees: "))
            result = calculate_sine(angle)
            print(f"The sine of {angle} degrees is {result:.3f}")

        elif choice == "2":
            angle = float(input("Enter the angle in degrees: "))
            result = calculate_cosine(angle)
            print(f"The cosine of {angle} degrees is {result:.3f}")

        elif choice == "3":
            print("Exiting...")
            break

        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

This program defines three functions: `calculate_sine()`, `calculate_cosine()`, and `main()`. The `main()` function handles user input and calls the appropriate calculation function based on the user's choice. The program also includes input validation to ensure that the user inputs a valid angle in degrees.
